    expect(decodeSnapshot(JSON.stringify({ ...example, note: 'é'.repeat(32768) }))).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { replayGame } from './replay.ts';
import { MAX_ELAPSED_MS } from './state.ts';

const sample = {
  version: 1, boardCode: 'np1-4-1',
  actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800,
};
const replay = (patch: Record<string, unknown> = {}) => replayGame(JSON.stringify({ ...sample, ...patch }));

describe('replay version 1', () => {
  it('replays the documented equal-time matching example in array order', () => {
    expect(replay()).toMatchObject({
      matched: [0, 11], moves: 1, elapsedMs: 800, selection: { kind: 'closed' }, started: true,
    });
  });

  it('starts the elapsed clock at the first valid action rather than timeline zero', () => {
    expect(replay({ actions: [{ atMs: 5000, index: 0 }], endMs: 5700 })?.elapsedMs).toBe(700);
    expect(replay({ actions: [], endMs: Number.MAX_SAFE_INTEGER })?.elapsedMs).toBe(0);
  });

  it('resolves mismatch expiration before an equal-time action', () => {
    const actions = [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 }, { atMs: 800, index: 2 }];
    expect(replay({ actions, endMs: 800 })).toMatchObject({
      moves: 1, elapsedMs: 800, selection: { kind: 'one', index: 2 },
    });
    expect(replay({ actions: [...actions.slice(0, 2), { atMs: 799, index: 2 }], endMs: 800 }))
      .toMatchObject({ moves: 1, selection: { kind: 'closed' } });
  });

  it('includes ignored repeated and matched activations without extra moves', () => {
    const actions = [...sample.actions.slice(0, 1), { atMs: 0, index: 0 },
      { atMs: 0, index: 11 }, { atMs: 1, index: 11 }];
    expect(replay({ actions })?.moves).toBe(1);
  });

  it('caps elapsed time while accepting safe-integer logical timestamps', () => {
    expect(replay({ endMs: Number.MAX_SAFE_INTEGER })?.elapsedMs).toBe(MAX_ELAPSED_MS);
    const actions = [{ atMs: Number.MAX_SAFE_INTEGER - 1, index: 0 }];
    expect(replay({ actions, endMs: Number.MAX_SAFE_INTEGER })?.elapsedMs).toBe(1);
  });

  it('stops time on the winning activation', () => {
    const pairs = [[0, 11], [1, 9], [2, 6], [3, 7], [4, 5], [8, 15], [10, 14], [12, 13]];
    const actions = pairs.flatMap((pair, time) => pair.map(index => ({ atMs: time, index })));
    expect(replay({ actions, endMs: 5000 })).toMatchObject({ moves: 8, elapsedMs: 7 });
  });

  it.each([
    { version: 2 }, { extra: true }, { boardCode: 'np1-4-01' },
    { endMs: -1 }, { endMs: 0.5 }, { endMs: Number.MAX_SAFE_INTEGER + 1 },
    { actions: [{ atMs: -1, index: 0 }] }, { actions: [{ atMs: 0.5, index: 0 }] },
    { actions: [{ atMs: 1, index: 0 }, { atMs: 0, index: 11 }] },
    { actions: [{ atMs: 801, index: 0 }] }, { actions: [{ atMs: 0, index: 16 }] },
    { actions: [{ atMs: 0, index: -1 }] }, { actions: [{ atMs: 0, index: 0.5 }] },
    { actions: [{ atMs: 0, index: 0, extra: true }] },
    { actions: [{ atMs: 0 }] }, { actions: null },
    { actions: Array.from({ length: 10001 }, () => ({ atMs: 0, index: 0 })) },
  ])('rejects invalid replay data %j', patch => {
    expect(replay(patch)).toBeNull();
  });

  it('enforces JSON byte and action limits', () => {
    expect(replay({ actions: Array.from({ length: 10000 }, () => ({ atMs: 0, index: 0 })) })).not.toBeNull();
    const text = JSON.stringify(sample);
    expect(replayGame(text + ' '.repeat(1048576 - text.length))).not.toBeNull();
    expect(replayGame(text + ' '.repeat(1048577 - text.length))).toBeNull();
    for (const malformed of ['{', 'null', '[]', '{}']) expect(replayGame(malformed)).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { activateCard } from './activateCard.ts';
import { createGame } from './createGame.ts';
import { isWon, MAX_MOVES, pairCount } from './state.ts';
import type { GameState } from './state.ts';
import { SUPPORTED_SIZES } from './boardCode.ts';

function initial(code = 'np1-4-1'): GameState {
  const state = createGame(code);
  if (!state) throw new Error('Invalid test board.');
  return state;
}

describe('card transitions', () => {
  it('starts on the first valid activation and ignores repeated and invalid cards', () => {
    const state = initial();
    for (const index of [-1, 16, 0.5, NaN]) expect(activateCard(state, index)).toBe(state);
    const one = activateCard(state, 0);
    expect(one.selection).toEqual({ kind: 'one', index: 0 });
    expect(one.started).toBe(true);
    expect(one.moves).toBe(0);
    expect(activateCard(one, 0)).toBe(one);
    expect(state.selection).toEqual({ kind: 'closed' });
  });

  it('matches immediately, counts exactly one move, and ignores matched cards', () => {
    const state = activateCard(activateCard(initial(), 0), 11);
    expect(state.matched).toEqual([0, 11]);
    expect(state.selection).toEqual({ kind: 'closed' });
    expect(state.moves).toBe(1);
    expect(pairCount(state)).toBe(1);
    expect(activateCard(state, 11)).toBe(state);
  });

  it('blocks every card while a mismatch is pending', () => {
    const state = activateCard(activateCard(initial(), 0), 1);
    expect(state.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 800 });
    expect(state.moves).toBe(1);
    for (let index = 0; index < 16; index += 1) expect(activateCard(state, index)).toBe(state);
  });

  it('continues matching and wins after the move cap', () => {
    const state = { ...initial(), moves: MAX_MOVES };
    const matched = activateCard(activateCard(state, 0), 11);
    expect(matched.moves).toBe(MAX_MOVES);
    expect(pairCount(matched)).toBe(1);
  });

  it('completes every supported size with whole pairs and no extra score', () => {
    for (const size of SUPPORTED_SIZES) {
      let state = initial(`np1-${size}-1`);
      for (let face = 0; face < size * size / 2; face += 1) {
        const first = state.deck.indexOf(face);
        const second = state.deck.lastIndexOf(face);
        state = activateCard(activateCard(state, first), second);
      }
      expect(isWon(state)).toBe(true);
      expect(state.moves).toBe(size * size / 2);
      expect(pairCount(state)).toBe(size * size / 2);
      expect(state.selection).toEqual({ kind: 'closed' });
      expect(activateCard(state, 0)).toBe(state);
    }
  });
});
import { describe, expect, it } from 'vitest';
import { activateCard } from './activateCard.ts';
import { advanceGame } from './advanceGame.ts';
import { createGame } from './createGame.ts';
import { formatTime } from './formatTime.ts';
import { MAX_ELAPSED_MS } from './state.ts';
import type { GameState } from './state.ts';

function initial(): GameState {
  const state = createGame('np1-4-1');
  if (!state) throw new Error('Invalid board.');
  return state;
}

describe('active logical time', () => {
  it('does not count before the first activation', () => {
    const state = initial();
    expect(advanceGame(state, 5000)).toBe(state);
    expect(advanceGame(activateCard(state, 0), 1234.5).elapsedMs).toBe(1234.5);
  });

  it('resolves a mismatch exactly at 800ms, regardless of update frequency', () => {
    const state = activateCard(activateCard(initial(), 0), 1);
    const waiting = advanceGame(state, 799);
    expect(waiting.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 1 });
    expect(advanceGame(waiting, 1)).toEqual(advanceGame(state, 800));
    expect(advanceGame(state, 800).selection).toEqual({ kind: 'closed' });
    expect(advanceGame(state, 850).elapsedMs).toBe(850);
  });

  it('caps elapsed time while mismatch time and later play keep working', () => {
    const state = activateCard(activateCard(initial(), 0), 1);
    const capped = advanceGame({ ...state, elapsedMs: MAX_ELAPSED_MS }, 800);
    expect(capped.elapsedMs).toBe(MAX_ELAPSED_MS);
    expect(capped.selection.kind).toBe('closed');
    expect(activateCard(capped, 2).selection).toEqual({ kind: 'one', index: 2 });
  });

  it('ignores invalid advances and stops at completion', () => {
    const state = activateCard(initial(), 0);
    for (const time of [0, -1, NaN, Infinity]) expect(advanceGame(state, time)).toBe(state);
    const complete = { ...state, matched: Array.from({ length: 16 }, (_, index) => index) };
    expect(advanceGame(complete, 800)).toBe(complete);
  });

  it.each([[0, '0:00'], [999, '0:00'], [1000, '0:01'], [60000, '1:00'],
    [3600000, '60:00'], [MAX_ELAPSED_MS, '5999:59']])('formats %d as %s', (time, text) => {
    expect(formatTime(Number(time))).toBe(text);
  });
});

