import { useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent, Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { arrowDestination } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
interface BoardProps {
  readonly game: GameState;
  readonly onActivate: (index: number) => void;
  readonly ref: Ref<BoardHandle>;
}

export function Board({ game, onActivate, ref }: BoardProps) {
  const [remembered, setRemembered] = useState(0);
  const grid = useRef<HTMLDivElement>(null);
  const focusCard = (index: number) => grid.current?.querySelectorAll<HTMLButtonElement>('button')[index]?.focus();
  useImperativeHandle(ref, () => ({ focusRemembered: () => focusCard(remembered) }), [remembered]);

  const moveFocus = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destination = arrowDestination(remembered, game.board.size, event.key);
    if (destination === null) return;
    event.preventDefault();
    focusCard(destination);
  };
  const { size } = game.board;
  const selection = game.selection;
  return <div className="board-scroll">
    <div ref={grid} className="board-grid" role="group" aria-label={`${size} by ${size} memory board`}
      aria-describedby="board-help" onKeyDown={moveFocus} style={{
        gridTemplateColumns: `repeat(${size}, minmax(44px, 88px))`,
        width: `${size * 88 + (size - 1) * 6}px`, minWidth: `${size * 44 + (size - 1) * 6}px`,
      }}>
      {game.deck.map((face, index) => {
        const matched = game.matched.includes(index);
        const revealed = matched || (selection.kind === 'one' && selection.index === index)
          || (selection.kind === 'mismatch' && (selection.first === index || selection.second === index));
        return <Card key={index} index={index} size={size} face={revealed ? face : null}
          matched={matched} tabIndex={index === remembered ? 0 : -1} onActivate={() => onActivate(index)}
          onFocus={card => { setRemembered(index); card.scrollIntoView({ block: 'nearest', inline: 'nearest' }); }} />;
      })}
    </div>
  </div>;
}
.board-scroll { max-width: 100%; width: fit-content; max-height: min(70dvh, 768px); margin: 0 auto; padding: 6px; overflow: auto; scroll-padding: 6px; border-radius: 8px; background: var(--panel); }
.board-grid { display: grid; gap: 6px; max-width: 100%; }
import { Face } from './Face.tsx';
import { faceIdentity } from './faceIdentity.ts';
import './Card.css';

interface CardProps {
  readonly index: number;
  readonly size: number;
  readonly face: number | null;
  readonly matched: boolean;
  readonly tabIndex: number;
  readonly onActivate: () => void;
  readonly onFocus: (card: HTMLButtonElement) => void;
}

export function Card({ index, size, face, matched, tabIndex, onActivate, onFocus }: CardProps) {
  const position = `Row ${Math.floor(index / size) + 1}, column ${index % size + 1}`;
  const name = face === null ? `${position}, closed`
    : `${position}, ${faceIdentity(face).name}, ${matched ? 'matched' : 'revealed'}`;
  return <button type="button" className={`card${face !== null ? ' card-revealed' : ''}${matched ? ' card-matched' : ''}`}
    aria-label={name} aria-disabled={matched ? true : undefined} tabIndex={tabIndex}
    onClick={onActivate} onFocus={event => onFocus(event.currentTarget)}>
    {face === null ? <span className="card-back" aria-hidden="true" /> : <Face id={face} />}
    {matched && <svg className="card-check" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
      <path d="M4 8 6 10 11 4" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>}
  </button>;
}
.card { width: 100%; min-width: 44px; min-height: 44px; aspect-ratio: 1; display: grid; place-items: center; position: relative; padding: 0; border: 2px solid var(--border); border-radius: 8px; background: var(--back); scroll-margin: 6px; transition: border-color 120ms; touch-action: manipulation; }
.card:hover { border-color: var(--text); }
.card:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.card-revealed { background: var(--face); }
.card-matched, .card-matched:hover { border-color: var(--green); opacity: 1; }
.card-back { width: 12px; height: 12px; border: 2px solid var(--border); transform: rotate(45deg); border-radius: 2px; }
.card-face { display: block; width: 100%; height: 100%; }
.card-check { position: absolute; right: 0; bottom: 0; width: 12px; height: 12px; color: var(--green); }
@media (prefers-reduced-motion: reduce) { .card { transition: none; } }

