import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { createGame } from '../src/game/createGame.ts';

export const PAIRS = [[0, 11], [1, 9], [2, 6], [3, 7], [4, 5], [8, 15], [10, 14], [12, 13]] as const;
export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export const cards = (page: Page) => page.locator('.board-grid button');
export const live = (page: Page) => page.locator('[aria-live="polite"]');

export async function openTools(page: Page) {
  if (!await page.getByLabel('Board code', { exact: true }).isVisible()) {
    await page.getByText('Reproduce a game', { exact: true }).click();
  }
}

export async function loadBoard(page: Page, code = 'np1-4-1') {
  await openTools(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
}

export async function loadSnapshot(page: Page, value: unknown) {
  await openTools(page);
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(JSON.stringify(value));
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
}

export function snapshot(size = 4, moves = size * size / 2) {
  return { version: 1, boardCode: `np1-${size}-1`,
    matched: Array.from({ length: size * size }, (_, i) => i),
    selection: { kind: 'closed' }, moves, elapsedMs: 1500, started: true };
}

export async function finish(page: Page, size = 4) {
  const state = createGame(`np1-${size}-1`);
  if (!state) throw new Error('Invalid fixture board.');
  for (let face = 0; face < size * size / 2; face += 1) {
    await cards(page).nth(state.deck.indexOf(face)).click();
    await cards(page).nth(state.deck.lastIndexOf(face)).click();
  }
  await expect(page.getByRole('region', { name: 'Game complete' })).toBeVisible();
}

export async function freezeClock(page: Page) {
  const time = new Date('2026-11-04T10:00:00Z');
  await page.clock.install({ time });
  await page.clock.pauseAt(new Date(time.getTime() + 100));
}

export async function exportValue(page: Page): Promise<unknown> {
  await openTools(page);
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  return JSON.parse(await page.getByLabel('Snapshot JSON', { exact: true }).inputValue());
}
import { expect, test } from '@playwright/test';
import { cards, exportValue, finish, freezeClock, live, loadBoard } from './gameFixtures.ts';

for (const size of [4, 6, 8, 10, 12, 14, 16]) {
  test(`finishes every pair on a ${size}x${size} board`, async ({ page }) => {
    await page.goto('/');
    await loadBoard(page, `np1-${size}-1`);
    await expect(cards(page)).toHaveCount(size * size);
    await finish(page, size);
    await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Best: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(cards(page).filter({ has: page.locator('.card-check') })).toHaveCount(size * size);
    await expect(live(page)).toContainText(`Pair found. All pairs found in ${size * size / 2} moves and `);
  });
}

test('counts second valid activations and resolves an exact active mismatch deadline', async ({ page }) => {
  await freezeClock(page);
  await page.goto('/');
  await loadBoard(page);
  await page.clock.runFor(5000);
  await expect(page.getByText('Time: 0:00', { exact: true })).toBeVisible();
  await cards(page).nth(0).click();
  await cards(page).nth(0).click();
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await cards(page).nth(11).click();
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await cards(page).nth(0).click({ force: true });
  await cards(page).nth(1).click();
  await cards(page).nth(2).click();
  await cards(page).nth(3).click();
  await expect(page.getByText('Moves: 2', { exact: true })).toBeVisible();
  await expect(cards(page).nth(3)).toHaveAccessibleName('Row 1, column 4, closed');
  await page.clock.runFor(799);
  await expect(cards(page).nth(1)).toHaveAccessibleName(/revealed$/);
  await page.clock.runFor(1);
  await expect(cards(page).nth(1)).toHaveAccessibleName(/closed$/);
  await expect(cards(page).nth(2)).toHaveAccessibleName(/closed$/);
  await expect(exportValue(page)).resolves.toMatchObject({ moves: 2, elapsedMs: 800 });
});

test('pauses the same mismatch and elapsed clock while hidden', async ({ page }) => {
  await freezeClock(page);
  await page.goto('/');
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(300);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, value: true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(10000);
  await expect(exportValue(page)).resolves.toMatchObject({ elapsedMs: 300, selection: { remainingMs: 500 } });
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, value: false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(499);
  await expect(cards(page).nth(0)).toHaveAccessibleName(/revealed$/);
  await page.clock.runFor(1);
  await expect(cards(page).nth(0)).toHaveAccessibleName(/closed$/);
  await expect(exportValue(page)).resolves.toMatchObject({ elapsedMs: 800 });
});

for (const action of ['Restart', 'New Game', 'size', 'load']) {
  test(`invalidates a pending mismatch after ${action}`, async ({ page }) => {
    await freezeClock(page);
    await page.goto('/');
    await loadBoard(page);
    await cards(page).nth(0).click();
    await cards(page).nth(1).click();
    const oldCode = await page.getByLabel('Board code', { exact: true }).inputValue();
    if (action === 'size') await page.getByLabel('Grid size').selectOption('6');
    else if (action === 'load') await loadBoard(page, 'np1-8-1');
    else {
      const button = page.getByRole('button', { name: action, exact: true });
      await button.click();
      await expect(button).toBeFocused();
    }
    await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
    if (action === 'Restart') await expect(page.getByLabel('Board code', { exact: true })).toHaveValue(oldCode);
    if (action === 'New Game') await expect(page.getByLabel('Board code', { exact: true })).not.toHaveValue(oldCode);
    await cards(page).nth(0).click();
    await page.clock.runFor(1600);
    await expect(cards(page).nth(0)).toHaveAccessibleName(/revealed$/);
    await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  });
}
import { expect, test } from '@playwright/test';
import { cards, exportValue, freezeClock, live, loadBoard, loadSnapshot, openTools, snapshot } from './gameFixtures.ts';

test('documents exact controls, preserves drafts and rejects invalid loads without replacing play', async ({ page }) => {
  await freezeClock(page);
  await page.goto('/');
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await expect(page.getByLabel('Grid size').locator('option')).toHaveText(['4x4', '6x6', '8x8', '10x10', '12x12', '14x14', '16x16']);
  await loadBoard(page, '  np1-4-1  ');
  await expect(page.getByRole('button', { name: 'Load board', exact: true })).toBeFocused();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-4-1');
  await expect(page.getByLabel('Board code', { exact: true })).toHaveAttribute('maxlength', '32');
  await expect(page.getByLabel('Snapshot JSON', { exact: true })).toHaveAttribute('maxlength', '65536');
  await page.getByLabel('Board code', { exact: true }).fill('np1-6-01');
  await cards(page).nth(0).click();
  await page.clock.runFor(1000);
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-6-01');
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(live(page)).toHaveText('Invalid board code.');
  await expect(cards(page)).toHaveCount(16);
  await expect(cards(page).nth(0)).toHaveAccessibleName(/revealed$/);
  await loadSnapshot(page, { version: 2 });
  await expect(live(page)).toHaveText('Invalid snapshot.');
  await expect(page.getByLabel('Snapshot JSON', { exact: true })).toHaveValue('{"version":2}');
  await expect(cards(page).nth(0)).toHaveAccessibleName(/revealed$/);
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-4-1');
});

test('exports readable whole milliseconds without pausing and restores unfinished progress paused', async ({ page }) => {
  await freezeClock(page);
  await page.goto('/');
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(123);
  await expect(exportValue(page)).resolves.toMatchObject({ version: 1, elapsedMs: 123, selection: { remainingMs: 677 } });
  await expect(page.getByRole('button', { name: 'Export snapshot', exact: true })).toBeFocused();
  await expect(page.getByLabel('Snapshot JSON', { exact: true })).toHaveValue(/\n  "version": 1,/);
  await page.clock.runFor(677);
  await expect(cards(page).nth(0)).toHaveAccessibleName(/closed$/);
  const value = { version: 1, boardCode: 'np1-4-1', matched: [0, 11],
    selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 },
    moves: 2, elapsedMs: 1500, started: true };
  await loadSnapshot(page, value);
  await expect(live(page)).toHaveText('Loaded snapshot. Select Resume to continue.');
  await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
  await cards(page).nth(3).click();
  await expect(cards(page).nth(3)).toHaveAccessibleName(/closed$/);
  await cards(page).nth(0).focus();
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowRight');
  await page.clock.runFor(10000);
  await expect(exportValue(page)).resolves.toMatchObject(value);
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await expect(cards(page).nth(5)).toBeFocused();
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await page.clock.runFor(299);
  await expect(cards(page).nth(1)).toHaveAccessibleName(/revealed$/);
  await page.clock.runFor(1);
  await expect(cards(page).nth(1)).toHaveAccessibleName(/closed$/);
  await expect(exportValue(page)).resolves.toMatchObject({ elapsedMs: 1800, moves: 2 });
});

test('completed imports are static, do not record best and contain no replay controls', async ({ page }) => {
  await page.goto('/');
  await loadSnapshot(page, snapshot(6));
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expect(live(page)).toHaveText('Loaded completed snapshot.');
  await expect(page.getByText('Best: none', { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await expect(page.locator('.win-banner')).toHaveCSS('animation-name', 'none');
  await expect(page.getByRole('button', { name: /replay/i })).toHaveCount(0);
  await openTools(page);
  await expect(exportValue(page)).resolves.toMatchObject(snapshot(6));
});

test('move and time caps remain playable through an imported final pair', async ({ page }) => {
  await freezeClock(page);
  await page.goto('/');
