import { formatTime } from './formatTime.ts';
import { isWon, pairCount } from './state.ts';
import type { GameState } from './state.ts';
import './Status.css';

interface StatusProps {
  readonly game: GameState;
  readonly best: number | null;
  readonly celebrate: boolean;
  readonly paused: boolean;
}

export function Status({ game, best, celebrate, paused }: StatusProps) {
  return <div className="status-area">
    <div className="game-stats" aria-label="Game statistics">
      <p><span>Moves: </span><strong>{game.moves}</strong></p>
      <p><span>Pairs: </span><strong>{pairCount(game)}/{game.deck.length / 2}</strong></p>
      <p><span>Time: </span><strong>{formatTime(game.elapsedMs)}</strong></p>
      <p><span>Best: </span><strong>{best ?? 'none'}</strong></p>
    </div>
    {isWon(game) && <section className={`win-banner${celebrate ? ' win-celebrate' : ''}`} aria-label="Game complete">
      <h2>All pairs found.</h2><p>Finished in {game.moves} moves and {formatTime(game.elapsedMs)}.</p>
    </section>}
    {paused && <p className="pause-note">Your snapshot is paused. Select Resume when you’re ready.</p>}
  </div>;
}

/work/src/game/controls/ReproductionCont.content:
import { useEffect, useState } from 'react';
import type { GameSession } from '../session/useGameSession.ts';
import './ReproductionControls.css';

interface ReproductionControlsProps {
  readonly session: GameSession;
  readonly onResume: () => void;
}

export function ReproductionControls({ session, onResume }: ReproductionControlsProps) {
  const [boardDraft, setBoardDraft] = useState(session.game.board.code);
  const [snapshotDraft, setSnapshotDraft] = useState('');
  const code = session.game.board.code;
  useEffect(() => { setBoardDraft(code); }, [session.dealId, code]);

  return <details className="reproduction">
    <summary>Reproduce a game</summary>
    <div className="reproduction-body">
      <p className="reproduction-help">Repeat a deal with its board code, or save your progress as a snapshot.</p>
      <div className="reproduction-field">
        <label htmlFor="board-code">Board code</label>
        <div className="board-load-row">
          <input id="board-code" type="text" maxLength={32} value={boardDraft} autoComplete="off" spellCheck={false}
            onChange={event => setBoardDraft(event.currentTarget.value)} />
          <button type="button" onClick={() => session.loadBoard(boardDraft)}>Load board</button>
        </div>
      </div>
      <div className="reproduction-field">
        <label htmlFor="snapshot-json">Snapshot JSON</label>
        <textarea id="snapshot-json" maxLength={65536} rows={6} value={snapshotDraft} spellCheck={false}
          onChange={event => setSnapshotDraft(event.currentTarget.value)} />
        <div className="snapshot-actions">
          <button type="button" onClick={() => setSnapshotDraft(session.exportSnapshot())}>Export snapshot</button>
          <button type="button" onClick={() => session.loadSnapshot(snapshotDraft)}>Load snapshot</button>
          {session.paused && <button type="button" onClick={onResume}>Resume</button>}
        </div>
      </div>
      {session.loadStatus && <p className="load-status">{session.loadStatus}</p>}
    </div>
  </details>;
}

/work/src/game/board/Board.tsx.content:
import { useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent, Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { arrowDestination } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
interface BoardProps {
  readonly game: GameState;
  readonly onActivate: (index: number) => void;
  readonly ref: Ref<BoardHandle>;
}

export function Board({ game, onActivate, ref }: BoardProps) {
  const [remembered, setRemembered] = useState(0);
  const grid = useRef<HTMLDivElement>(null);
  const focusCard = (index: number) => grid.current?.querySelectorAll<HTMLButtonElement>('button')[index]?.focus();
  useImperativeHandle(ref, () => ({ focusRemembered: () => focusCard(remembered) }), [remembered]);

  const moveFocus = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destination = arrowDestination(remembered, game.board.size, event.key);
    if (destination === null) return;
    event.preventDefault();
    focusCard(destination);
  };
  const { size } = game.board;
  const selection = game.selection;
  return <div className="board-scroll">
    <div ref={grid} className="board-grid" role="group" aria-label={`${size} by ${size} memory board`}
      aria-describedby="board-help" onKeyDown={moveFocus} style={{
        gridTemplateColumns: `repeat(${size}, minmax(44px, 88px))`,
        width: `${size * 88 + (size - 1) * 6}px`, minWidth: `${size * 44 + (size - 1) * 6}px`,
      }}>
      {game.deck.map((face, index) => {
        const matched = game.matched.includes(index);
        const revealed = matched || (selection.kind === 'one' && selection.index === index)
          || (selection.kind === 'mismatch' && (selection.first === index || selection.second === index));
        return <Card key={index} index={index} size={size} face={revealed ? face : null}
          matched={matched} tabIndex={index === remembered ? 0 : -1} onActivate={() => onActivate(index)}
          onFocus={card => { setRemembered(index); card.scrollIntoView({ block: 'nearest', inline: 'nearest' }); }} />;
      })}
    </div>
  </div>;
}

/work/src/game/board/navigation.ts.content:
export function arrowDestination(index: number, size: number, key: string): number | null {
  const row = Math.floor(index / size);
  const column = index % size;
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return row > 0 ? index - size : index;
    case 'ArrowDown': return row < size - 1 ? index + size : index;
    default: return null;
  }
}

